import { SignMessageOptions, SignMessageResponse } from '../types';
import { PopupManager } from '../popup';
import { MessageManager } from '../messaging';
import { PopupClosedError, TimeoutError } from '../errors';
import { MESSAGE_TYPES, DEFAULT_SIGN_POPUP_HEIGHT } from '../constants';

export async function signMessage(
  walletUrl: string,
  options: SignMessageOptions,
  popupManager: PopupManager,
  messageManager: MessageManager,
  timeout: number
): Promise<SignMessageResponse> {
  const { message, onProgress } = options;

  onProgress?.('Preparing message...');

  // Encode message as base64
  const encodedMsg = btoa(message);

  // Build sign-message URL (no network needed)
  const url = `${walletUrl}/sign-message?msg=${encodeURIComponent(encodedMsg)}`;

  onProgress?.('Opening wallet...');

  // Open popup
  popupManager.open(url, 'xyra_sign_message', {
    height: DEFAULT_SIGN_POPUP_HEIGHT,
    centered: true
  });

  onProgress?.('Waiting for signature...');

  // Setup popup close detection
  const closedPromise = new Promise<never>((_, reject) => {
    popupManager.onClose(() => {
      reject(new PopupClosedError());
    });
  });

  // Setup timeout
  const timeoutPromise = new Promise<never>((_, reject) => {
    setTimeout(() => reject(new TimeoutError()), timeout);
  });

  // Wait for sign message response
  const responsePromise = messageManager.waitForMessage<SignMessageResponse>(
    MESSAGE_TYPES.SIGN_MESSAGE_RESPONSE,
    timeout
  );

  try {
    const response = await Promise.race([
      responsePromise,
      closedPromise,
      timeoutPromise
    ]);

    onProgress?.('Message signed!');
    popupManager.close();

    return response;
  } catch (error) {
    popupManager.close();
    throw error;
  }
}
