import { SignOptions, SignResponse } from '../types';
import { PopupManager } from '../popup';
import { MessageManager } from '../messaging';
import { PopupClosedError, TimeoutError } from '../errors';
import { MESSAGE_TYPES, DEFAULT_SIGN_POPUP_HEIGHT } from '../constants';

export async function sign(
  walletUrl: string,
  options: SignOptions,
  popupManager: PopupManager,
  messageManager: MessageManager,
  timeout: number
): Promise<SignResponse> {
  const { transaction, network, submit = false, onProgress } = options;

  onProgress?.('Preparing transaction...');

  // Encode transaction as base64
  const encodedTx = btoa(JSON.stringify(transaction));

  // Build sign URL (no session needed)
  const url =
    `${walletUrl}/sign` +
    `?tx=${encodeURIComponent(encodedTx)}` +
    `&network=${encodeURIComponent(network)}` +
    (submit ? `&submit=true` : '');

  onProgress?.('Opening wallet...');

  // Open popup
  const popup = popupManager.open(url, 'xyra_sign', {
    height: DEFAULT_SIGN_POPUP_HEIGHT,
    centered: true
  });

  // Optionally send postMessage with submit flag
  if (submit) {
    setTimeout(() => {
      popup.postMessage(
        {
          type: 'SIGN',
          network,
          tx: encodedTx,
          submit: true
        },
        new URL(walletUrl).origin
      );
    }, 500);
  }

  onProgress?.('Waiting for signature...');

  // Setup popup close detection
  const closedPromise = new Promise<never>((_, reject) => {
    popupManager.onClose(() => {
      reject(new PopupClosedError());
    });
  });

  // Setup timeout
  const timeoutPromise = new Promise<never>((_, reject) => {
    setTimeout(() => reject(new TimeoutError()), timeout);
  });

  // Wait for sign response
  const responsePromise = messageManager.waitForMessage<SignResponse>(
    MESSAGE_TYPES.SIGN_RESPONSE,
    timeout
  );

  try {
    const response = await Promise.race([
      responsePromise,
      closedPromise,
      timeoutPromise
    ]);

    onProgress?.(response.submitted ? 'Transaction submitted!' : 'Transaction signed!');
    popupManager.close();

    return response;
  } catch (error) {
    popupManager.close();
    throw error;
  }
}
