import {
  XyraSDKConfig,
  ConnectOptions,
  ConnectResponse,
  SignOptions,
  SignResponse,
  SignMessageOptions,
  SignMessageResponse,
  Network
} from './types';
import { PopupManager } from './popup';
import { MessageManager } from './messaging';
import { connect } from './methods/connect';
import { sign } from './methods/sign';
import { signMessage } from './methods/signMessage';
import { DEFAULT_WALLET_URL, DEFAULT_TIMEOUT } from './constants';
import { InvalidNetworkError } from './errors';

export class XyraSDK {
  private config: Required<XyraSDKConfig>;
  private popupManager: PopupManager;
  private messageManager: MessageManager;

  constructor(config: XyraSDKConfig = {}) {
    this.config = {
      walletUrl: config.walletUrl || DEFAULT_WALLET_URL,
      popupWidth: config.popupWidth || 420,
      popupHeight: config.popupHeight || 720,
      signPopupHeight: config.signPopupHeight || 640,
      timeout: config.timeout || DEFAULT_TIMEOUT
    };

    this.popupManager = new PopupManager();
    this.messageManager = new MessageManager(this.config.walletUrl);

    // Start listening for messages
    this.messageManager.startListening();
  }

  /**
   * Connect to Xyra wallet
   */
  async connect(options: ConnectOptions): Promise<ConnectResponse> {
    this.validateNetwork(options.network);

    return connect(
      this.config.walletUrl,
      options,
      this.popupManager,
      this.messageManager,
      this.config.timeout
    );
  }

  /**
   * Sign a transaction
   */
  async sign(options: Omit<SignOptions, 'submit'>): Promise<SignResponse> {
    this.validateNetwork(options.network);

    return sign(
      this.config.walletUrl,
      { ...options, submit: false },
      this.popupManager,
      this.messageManager,
      this.config.timeout
    );
  }

  /**
   * Sign and submit a transaction
   */
  async signAndSubmit(options: Omit<SignOptions, 'submit'>): Promise<SignResponse> {
    this.validateNetwork(options.network);

    return sign(
      this.config.walletUrl,
      { ...options, submit: true },
      this.popupManager,
      this.messageManager,
      this.config.timeout
    );
  }

  /**
   * Sign an arbitrary message
   */
  async signMessage(options: SignMessageOptions): Promise<SignMessageResponse> {
    // No network validation needed - signing is network-agnostic

    return signMessage(
      this.config.walletUrl,
      options,
      this.popupManager,
      this.messageManager,
      this.config.timeout
    );
  }

  /**
   * Validate network string
   */
  private validateNetwork(network: string): void {
    const validNetworks: Network[] = [
      'xrpl-mainnet',
      'xrpl-testnet',
      'xahau-mainnet',
      'xahau-testnet'
    ];

    if (!validNetworks.includes(network as Network)) {
      throw new InvalidNetworkError(network);
    }
  }

  /**
   * Cleanup resources
   */
  destroy(): void {
    this.popupManager.destroy();
    this.messageManager.destroy();
  }
}
