import { DEFAULT_WALLET_URL } from './constants';

export type MessageHandler = (data: any) => void;

export class MessageManager {
  private walletOrigin: string;
  private listeners: Map<string, MessageHandler[]> = new Map();
  private boundHandler: ((event: MessageEvent) => void) | null = null;

  constructor(walletUrl: string = DEFAULT_WALLET_URL) {
    this.walletOrigin = new URL(walletUrl).origin;
  }

  /**
   * Start listening for messages from wallet
   */
  startListening(): void {
    if (this.boundHandler) return;

    this.boundHandler = this.handleMessage.bind(this);
    window.addEventListener('message', this.boundHandler);
  }

  /**
   * Stop listening for messages
   */
  stopListening(): void {
    if (this.boundHandler) {
      window.removeEventListener('message', this.boundHandler);
      this.boundHandler = null;
    }
  }

  /**
   * Add a listener for a specific message type
   */
  on(type: string, handler: MessageHandler): void {
    if (!this.listeners.has(type)) {
      this.listeners.set(type, []);
    }
    this.listeners.get(type)!.push(handler);
  }

  /**
   * Remove a listener
   */
  off(type: string, handler: MessageHandler): void {
    const handlers = this.listeners.get(type);
    if (handlers) {
      const index = handlers.indexOf(handler);
      if (index > -1) {
        handlers.splice(index, 1);
      }
    }
  }

  /**
   * Remove all listeners for a type
   */
  offAll(type: string): void {
    this.listeners.delete(type);
  }

  /**
   * Handle incoming messages
   */
  private handleMessage(event: MessageEvent): void {
    // Security: Verify origin
    if (event.origin !== this.walletOrigin) {
      return;
    }

    const { type, ...data } = event.data || {};

    if (!type) return;

    // Call all listeners for this message type
    const handlers = this.listeners.get(type);
    if (handlers) {
      handlers.forEach(handler => handler(data));
    }
  }

  /**
   * Wait for a specific message type with timeout
   */
  waitForMessage<T = any>(type: string, timeout: number = 300000): Promise<T> {
    return new Promise((resolve, reject) => {
      const timeoutId = setTimeout(() => {
        this.off(type, handler);
        reject(new Error(`Timeout waiting for message: ${type}`));
      }, timeout);

      const handler = (data: T) => {
        clearTimeout(timeoutId);
        this.off(type, handler);
        resolve(data);
      };

      this.on(type, handler);
    });
  }

  /**
   * Cleanup
   */
  destroy(): void {
    this.stopListening();
    this.listeners.clear();
  }
}
