import { DEFAULT_POPUP_WIDTH, DEFAULT_POPUP_HEIGHT, POPUP_FEATURES } from './constants';
import { PopupBlockedError } from './errors';

export interface PopupOptions {
  width?: number;
  height?: number;
  centered?: boolean;
}

export class PopupManager {
  private popup: Window | null = null;
  private checkInterval: ReturnType<typeof setInterval> | null = null;

  /**
   * Open a popup window with the given URL
   */
  open(url: string, name: string, options: PopupOptions = {}): Window {
    const width = options.width || DEFAULT_POPUP_WIDTH;
    const height = options.height || DEFAULT_POPUP_HEIGHT;

    const features = this.buildFeatures(width, height, options.centered);

    this.popup = window.open(url, name, features);

    if (!this.popup) {
      throw new PopupBlockedError();
    }

    return this.popup;
  }

  /**
   * Check if popup is still open
   */
  isOpen(): boolean {
    return this.popup !== null && !this.popup.closed;
  }

  /**
   * Close the popup if it's open
   */
  close(): void {
    if (this.popup && !this.popup.closed) {
      this.popup.close();
    }
    this.popup = null;
  }

  /**
   * Focus the popup window
   */
  focus(): void {
    if (this.isOpen() && this.popup) {
      this.popup.focus();
    }
  }

  /**
   * Monitor popup and call callback when it closes
   */
  onClose(callback: () => void): void {
    this.stopMonitoring();

    this.checkInterval = setInterval(() => {
      if (!this.isOpen()) {
        this.stopMonitoring();
        callback();
      }
    }, 500);
  }

  /**
   * Stop monitoring popup state
   */
  private stopMonitoring(): void {
    if (this.checkInterval) {
      clearInterval(this.checkInterval);
      this.checkInterval = null;
    }
  }

  /**
   * Build window.open features string
   */
  private buildFeatures(width: number, height: number, centered: boolean = true): string {
    let features = Object.entries(POPUP_FEATURES)
      .map(([key, value]) => `${key}=${value}`)
      .join(',');

    features += `,width=${width},height=${height}`;

    if (centered) {
      const left = Math.round((window.screen.width - width) / 2);
      const top = Math.round((window.screen.height - height) / 2);
      features += `,left=${left},top=${top}`;
    }

    return features;
  }

  /**
   * Cleanup
   */
  destroy(): void {
    this.stopMonitoring();
    this.close();
  }
}
