import { ConnectOptions, ConnectResponse } from '../types';
import { PopupManager } from '../popup';
import { MessageManager } from '../messaging';
import { PopupClosedError, TimeoutError } from '../errors';
import { MESSAGE_TYPES, DEFAULT_POPUP_HEIGHT } from '../constants';

export async function connect(
  walletUrl: string,
  options: ConnectOptions,
  popupManager: PopupManager,
  messageManager: MessageManager,
  timeout: number
): Promise<ConnectResponse> {
  const { network, onProgress } = options;

  onProgress?.('Opening wallet...');

  // Build connect URL
  const url = `${walletUrl}/connect?network=${encodeURIComponent(network)}`;

  // Open popup
  popupManager.open(url, 'xyra_connect', {
    height: DEFAULT_POPUP_HEIGHT,
    centered: true
  });

  onProgress?.('Waiting for user approval...');

  // Setup popup close detection
  const closedPromise = new Promise<never>((_, reject) => {
    popupManager.onClose(() => {
      reject(new PopupClosedError());
    });
  });

  // Setup timeout
  const timeoutPromise = new Promise<never>((_, reject) => {
    setTimeout(() => reject(new TimeoutError()), timeout);
  });

  // Wait for connect response
  const responsePromise = messageManager.waitForMessage<ConnectResponse>(
    MESSAGE_TYPES.CONNECT_RESPONSE,
    timeout
  );

  try {
    const response = await Promise.race([
      responsePromise,
      closedPromise,
      timeoutPromise
    ]);

    onProgress?.('Connected!');
    popupManager.close();

    return response;
  } catch (error) {
    popupManager.close();
    throw error;
  }
}
