export class XyraError extends Error {
  constructor(message: string, public code?: string) {
    super(message);
    this.name = 'XyraError';
  }
}

export class PopupBlockedError extends XyraError {
  constructor() {
    super('Popup was blocked by the browser. Please allow popups for this site.', 'POPUP_BLOCKED');
    this.name = 'PopupBlockedError';
  }
}

export class PopupClosedError extends XyraError {
  constructor() {
    super('User closed the popup before completing the action.', 'POPUP_CLOSED');
    this.name = 'PopupClosedError';
  }
}

export class TimeoutError extends XyraError {
  constructor() {
    super('Request timed out. Please try again.', 'TIMEOUT');
    this.name = 'TimeoutError';
  }
}

export class InvalidNetworkError extends XyraError {
  constructor(network: string) {
    super(`Invalid network: ${network}`, 'INVALID_NETWORK');
    this.name = 'InvalidNetworkError';
  }
}

export class SessionExpiredError extends XyraError {
  constructor() {
    super('Session has expired. Please reconnect.', 'SESSION_EXPIRED');
    this.name = 'SessionExpiredError';
  }
}
